/**
 * E0 — the reproducible characterization baseline for T2 S8.
 *
 * The baseline is not a screenshot. It records the plain inputs and decisions
 * the renderer made before this program: each catalogue descriptor, Treatment
 * readings, the S4 single-image Finish, a palette follower, a rotated
 * non-square mapping, the normal scale/flip pair, the two-UV sampling plan, and
 * the two known defects (one texture cache for colour and data; no Region UV
 * attribute). The fixtures are generated by
 * `scripts/build-s8-characterization-fixtures.ts` and pinned here by SHA.
 *
 * Regenerate intentionally with `S8_BASELINE=write npx vitest run ...`. A
 * changed baseline without a renderer change is a failure, not a refresh.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterEach, describe, expect, it } from 'vitest';
import { NoColorSpace, SRGBColorSpace, Texture } from 'three';
import {
	CATALOGUE_MATERIAL_IDS,
	bindFinish,
	catalogueRecipe,
	readRecipe,
	recipeHash,
	resolveFinish,
	shippedImageIndex
} from '@portfolio/project-model/materials';
import {
	buildRegionMeshGeometry
} from '$lib/render/layout/region-mesh-builder';
import {
	__resetDefaultSourceLoaderForTests,
	loadMaterialTextures,
	resetTextureCachesForTests,
	setDefaultTextureSourceLoader
} from '$lib/render/resources/texture-store';
import {
	resolveSceneMaterial,
	sceneLookFor,
	type LookSource
} from '$lib/render/materials/scene-instance-material';
import type { LayoutRegion } from '@portfolio/layout-core';
import {
	compileWallFirstLayoutGeometryFresh,
	createEmptyWallFirstLayoutDocument
} from '@portfolio/layout-core';
import type { MaterialDefinition, MaterialId } from '$lib/types/materials';
import type { SceneDocument, SceneMaterialInstance, SceneTextureAsset } from '$lib/content/scene';
import {
	FORM_FACTS,
	MODEL_FACTS,
	TWO_UV_FACTS,
	fixtureImageIndex,
	fullRecipe
} from '../../project-model/materials/fixtures';

const HERE = dirname(fileURLToPath(import.meta.url));
const FIXTURE_DIR = resolve(HERE, '__fixtures__/s8');
const BASELINE_PATH = resolve(FIXTURE_DIR, 'e0-baseline.json');
const MANIFEST_PATH = resolve(FIXTURE_DIR, 'fixtures.json');
const REPO_REVISION = '30da19b3';

const S8_TEXTURE: SceneTextureAsset = {
	id: 's8-swatch',
	name: 'S8 Swatch',
	uri: '/s8-fixtures/swatch-rgba.png'
};
const S8_TEXTURE_HASH = `sha256-${'7'.repeat(64)}`;

const WOOD: SceneMaterialInstance = { id: 's8-wood', name: 'S8 Wood', base: { catalogue: 'wood-walnut' }, overrides: { maps: { color: { image: { textureId: 's8-swatch' } } }, mapping: { kind: 'target', metric: { tileMeters: [0.8, 1.6], rotation: 0.42, offset: [0.25, 0.5] } } } };

function lookSource(
	materials: SceneMaterialInstance[] = [],
	environment?: LookSource['environment']
): LookSource {
	return {
		textures: [S8_TEXTURE],
		materialIndex: {
			definitions: new Map(),
			definitionImages: new Map(),
			images: [{ hash: S8_TEXTURE_HASH, source: { textureId: S8_TEXTURE.id } }]
		},
		materials,
		palette: [{ id: 's8-walnut', name: 'Walnut', color: '#5a3a22' }],
		...(environment === undefined ? {} : { environment })
	};
}

function currentLook(testCase: {
	materials?: SceneMaterialInstance[];
	fallback: MaterialId;
	instanceId?: string;
	environment?: LookSource['environment'];
	surface: [number, number];
}) {
	return sceneLookFor(
		lookSource(testCase.materials ?? [], testCase.environment),
		{ materialInstanceId: testCase.instanceId ?? null, fallbackCatalogueId: testCase.fallback },
		testCase.surface
	);
}

async function defectTextureOrder() {
	const shared = '/s8-fixtures/shared-source.png';
	const colour: MaterialDefinition = {
		id: 'plaster-warm',
		label: 'S8 defect colour',
		textures: { map: shared },
		fallbackColor: '#ffffff',
		roughness: 1,
		metalness: 0
	};
	const data: MaterialDefinition = {
		id: 'wood-walnut',
		label: 'S8 defect data',
		textures: { roughnessMap: shared },
		fallbackColor: '#ffffff',
		roughness: 1,
		metalness: 0
	};
	setDefaultTextureSourceLoader(async () => new Texture());
	try {
		resetTextureCachesForTests();
		const colourFirstColour = await loadMaterialTextures(colour);
		const colourFirstData = await loadMaterialTextures(data);
		const colourFirst = {
			mapColorSpace: colourFirstColour.status === 'ready' ? colourFirstColour.maps.map?.colorSpace ?? null : null,
			roughnessMapColorSpace:
				colourFirstData.status === 'ready'
					? colourFirstData.maps.roughnessMap?.colorSpace ?? null
					: null
		};

		resetTextureCachesForTests();
		const dataFirstData = await loadMaterialTextures(data);
		const dataFirstColour = await loadMaterialTextures(colour);
		const dataFirst = {
			roughnessMapColorSpace:
				dataFirstData.status === 'ready'
					? dataFirstData.maps.roughnessMap?.colorSpace ?? null
					: null,
			mapColorSpace:
				dataFirstColour.status === 'ready' ? dataFirstColour.maps.map?.colorSpace ?? null : null
		};

		const byte = 128;
		const raw = byte / 255;
		const srgb = raw <= 0.04045 ? raw / 12.92 : ((raw + 0.055) / 1.055) ** 2.4;
		// The last bit of `** 2.4` differs between V8 versions. The baseline is a
		// transfer-function observation, not a bit-exact numeric oracle.
		const colourRead = Number(srgb.toFixed(12));
		return {
			sharedUri: shared,
			firstVerified: 'one Texture cached by URI; the first slot decides its colorSpace',
			byte,
			rawRead: raw,
			colourRead,
			expected: { colourSlot: SRGBColorSpace, dataSlot: NoColorSpace },
			colourFirst,
			dataFirst
		};
	} finally {
		resetTextureCachesForTests();
		__resetDefaultSourceLoaderForTests();
	}
}

function defectRegionUv() {
	const region: LayoutRegion = {
		id: 's8-floor',
		role: 'floor',
		elevation: 0,
		thickness: 0.2,
		footprint: {
			kind: 'polygon',
			points: [
				[1, -3],
				[3, -3],
				[3, -1],
				[1, -1]
			]
		},
		form: { kind: 'flat' },
		intendedGaps: []
	};
	const document = { ...createEmptyWallFirstLayoutDocument(), regions: [region] };
	const compiled = compileWallFirstLayoutGeometryFresh(document);
	if (compiled.issues.length > 0) throw new Error(JSON.stringify(compiled.issues));
	const buffer = buildRegionMeshGeometry(compiled.geometry.regions[0]!);
	const uv = buffer.getAttribute('uv');
	const result = {
		surface: 'top + underside + edge of one rectangular slab',
		hasUv: uv !== undefined,
		attributes: Object.keys(buffer.attributes).sort(),
		groups: buffer.groups.length,
		vertexCount: buffer.getAttribute('position').count,
		surfaceCount: (buffer.userData.regionSurfaces as readonly string[]).length,
		expected: { hasUv: true, mapping: 'metric planar UV0 on every face' }
	};
	buffer.dispose();
	return result;
}

function pureReadings() {
	const read = readRecipe(fullRecipe());
	if (!read.success) throw new Error(JSON.stringify(read.issues));
	const resolution = resolveFinish(
		{ material: read.recipe },
		undefined,
		undefined,
		fixtureImageIndex()
	);
	if (resolution.inputs === null) throw new Error(JSON.stringify(resolution.issues));
	const form = bindFinish(resolution, { subject: FORM_FACTS.subject, facts: FORM_FACTS });
	const model = bindFinish(resolution, { subject: MODEL_FACTS.subject, facts: MODEL_FACTS });
	const uv1 = bindFinish(
		resolveFinish(
			{ material: read.recipe },
			{ mapping: { kind: 'uv', set: 1, repeat: [2, 3], rotation: 1.2, offset: [0.1, 0.9] } },
			undefined,
			fixtureImageIndex()
		),
		{ subject: TWO_UV_FACTS.subject, facts: TWO_UV_FACTS }
	);
	return { read, resolution, form, model, uv1 };
}

function samplePlan(bound: ReturnType<typeof bindFinish>['bound']) {
	return bound?.samples.map((sample) => ({
		role: sample.role,
		uvSet: sample.uvSet,
		basis: sample.basis,
		repeat: sample.repeat,
		rotation: sample.rotation,
		offset: sample.offset,
		...(sample.component === undefined ? {} : { component: sample.component }),
		...(sample.invert === undefined ? {} : { invert: sample.invert }),
		...(sample.convention === undefined ? {} : { convention: sample.convention }),
		image: sample.image.source
	}));
}

async function captureBaseline() {
	const fixtures = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8')) as {
		fixtures: { id: string; file: string; sha256: string; byteSize: number }[];
	};
	const fixturePins = fixtures.fixtures.map((fixture) => {
		const bytes = readFileSync(resolve(FIXTURE_DIR, fixture.file));
		const actual = `sha256-${createHash('sha256').update(new Uint8Array(bytes)).digest('hex')}`;
		return {
			id: fixture.id,
			file: fixture.file,
			sha256: actual,
			byteSize: bytes.byteLength
		};
	});

	const catalogue = [];
	for (const id of CATALOGUE_MATERIAL_IDS) {
		const recipe = catalogueRecipe(id);
		if (recipe === undefined) throw new Error(id);
		catalogue.push({
			id,
			recipeHash: await recipeHash(recipe),
			natural: currentLook({ fallback: id, surface: [2, 2] })
		});
	}

	const pure = pureReadings();
	const disabledBase = readRecipe(fullRecipe());
	if (!disabledBase.success) throw new Error(JSON.stringify(disabledBase.issues));
	// A disabled map is an instance override: the complete recipe never carries
	// null, and the override reader is the one that admits it.
	const disabledResolved = resolveFinish(
		{ material: disabledBase.recipe },
		{ maps: { normal: null } },
		undefined,
		fixtureImageIndex()
	);
	const minusY = readRecipe({
		...fullRecipe(),
		maps: {
			...fullRecipe().maps,
			normal: { image: fullRecipe().maps.normal!.image, convention: '-Y' }
		}
	});
	if (!minusY.success) throw new Error(JSON.stringify(minusY.issues));
	const minusYResolved = resolveFinish(
		{ material: minusY.recipe },
		undefined,
		undefined,
		fixtureImageIndex()
	);

	return {
		schemaVersion: 1,
		profile: 'pbr-metallic-roughness/v1',
		fixturesManifest: 'fixtures.json',
		environmentEvidence: 'evidence/e0-environment.json',
		pixelBaseline: {
			status: 'captured',
			requirement:
				'Before replacing the Scene resolver or sampling path, PR B must capture the pre-change product-canvas rendering for the catalogue, S4 image, palette follower, shared Form/GLB and each Treatment, label its software renderer, and retain those pixels as the replacement oracle.',
			artifacts: 'apps/editor/tests/lib/render/materials/__fixtures__/s8/pixels/capture.json'
		},
		charts: {
			swatchGrey: { fixture: 'swatch-rgba', patch: [64, 64], bytes: [128, 128, 128, 255] },
			checkerWhite: { fixture: 'checker-asymmetric', patch: [48, 48], bytes: [255, 255, 255, 255] },
			checkerMagentaMarker: { fixture: 'checker-asymmetric', patch: [100, 52], bytes: [240, 20, 240, 255] },
			normalPlusY: { fixture: 'normal-plus-y', patch: [64, 64], bytes: [166, 204, 222, 255] },
			normalMinusY: { fixture: 'normal-minus-y', patch: [64, 64], bytes: [166, 51, 222, 255] },
			ormCentre: { fixture: 'orm-distinct', patch: [64, 64], bytes: [51, 191, 255, 255] },
			note: 'patch is the top-left pixel of the named interior; the fixture manifest records the full rectangles'
		},
		capturedFrom: {
			repository: 'Biskiq/spatial-sketch-editor',
			mainRevision: REPO_REVISION,
			planningPr: 386,
			rendererPr: 385,
			note: 'captured before S8 renderer changes; regenerate only with a deliberate renderer change'
		},
		fixtures: fixturePins,
		catalogue,
		appearance: {
			s4SingleImage: currentLook({
				materials: [
					{ id: 's8-wood', name: 'S8 Wood', base: { catalogue: 'wood-walnut' }, overrides: { maps: { color: { image: { textureId: 's8-swatch' } } } } }
				],
				instanceId: 's8-wood',
				fallback: 'wood-walnut',
				surface: [2.4, 1.1]
			}),
			paletteFollower: currentLook({
				materials: [
					{ id: 's8-follower', name: 'S8 Follower', base: { catalogue: 'paper-aged' }, overrides: { color: { slot: 's8-walnut' } } }
				],
				instanceId: 's8-follower',
				fallback: 'paper-aged',
				surface: [2, 2]
			}),
			sharedRotatedNonSquare: currentLook({
				materials: [WOOD],
				instanceId: 's8-wood',
				fallback: 'wood-walnut',
				surface: [3.2, 1.6]
			}),
			treatments: {
				natural: currentLook({ materials: [WOOD], instanceId: 's8-wood', fallback: 'wood-walnut', surface: [2, 2] }),
				clay: currentLook({
					materials: [WOOD],
					instanceId: 's8-wood',
					fallback: 'wood-walnut',
					surface: [2, 2],
					environment: { treatment: 'clay' }
				}),
				flatColour: currentLook({
					materials: [WOOD],
					instanceId: 's8-wood',
					fallback: 'wood-walnut',
					surface: [2, 2],
					environment: { treatment: 'flat-colour' }
				})
			},
			authoredZero: currentLook({
				materials: [
					{ id: 's8-zero', name: 'S8 Zero', base: { catalogue: 'wood-walnut' }, overrides: { roughness: 0, metalness: 0 } }
				],
				instanceId: 's8-zero',
				fallback: 'wood-walnut',
				surface: [1, 1]
			}),
			missingOptionalMap: currentLook({ fallback: 'marble-light', surface: [2, 2] })
		},
		contract: {
			form: samplePlan(pure.form.bound),
			model: samplePlan(pure.model.bound),
			uv1Mirrored: samplePlan(pure.uv1.bound),
			orm: {
				roughness: pure.resolution.inputs?.maps.roughness,
				metalness: pure.resolution.inputs?.maps.metalness,
				occlusion: pure.resolution.inputs?.maps.occlusion
			},
			disabledNormal: {
				normal: disabledResolved.inputs?.maps.normal ?? null,
				provenance: disabledResolved.inputs?.provenance.maps.normal
			},
			minusYNormal: {
				convention: minusYResolved.inputs?.maps.normal?.convention,
				normalScale: minusYResolved.inputs?.normalScale
			}
		},
		defects: {
			textureStoreSharedSource: await defectTextureOrder(),
			regionUv: defectRegionUv()
		}
	};
}

afterEach(() => {
	resetTextureCachesForTests();
	__resetDefaultSourceLoaderForTests();
});

describe('E0 characterization baseline', () => {
	it('pins every generated fixture to the committed bytes', async () => {
		const baseline = await captureBaseline();
		for (const fixture of baseline.fixtures) {
			expect(fixture.sha256, fixture.id).toMatch(/^sha256-[0-9a-f]{64}$/);
			expect(fixture.byteSize, fixture.id).toBeGreaterThan(0);
		}
		expect(baseline.fixtures.map((fixture) => fixture.id)).toEqual([
			'swatch-rgba',
			'checker-asymmetric',
			'normal-plus-y',
			'normal-minus-y',
			'orm-distinct',
			'two-uv-glb'
		]);
	});

	it('records the corrected colour/data decode after the role-keyed cache', async () => {
		const baseline = await captureBaseline();
		const defect = baseline.defects.textureStoreSharedSource;
		expect(defect.expected).toEqual({ colourSlot: 'srgb', dataSlot: '' });
		expect(defect.colourFirst).toEqual({ mapColorSpace: 'srgb', roughnessMapColorSpace: '' });
		expect(defect.dataFirst).toEqual({ roughnessMapColorSpace: '', mapColorSpace: 'srgb' });
		expect(defect.rawRead).toBeCloseTo(128 / 255, 15);
		expect(defect.colourRead).toBeCloseTo(0.215860500114, 12);
	});

	it('records the Region UV attribute after B added the metric chart', async () => {
		const baseline = await captureBaseline();
		expect(baseline.defects.regionUv.hasUv).toBe(true);
		expect(baseline.defects.regionUv.attributes).toEqual(['normal', 'position', 'uv']);
		expect(baseline.defects.regionUv.surfaceCount).toBeGreaterThan(0);
	});

	it('resolves the shared Finish to both a Form and a legacy GLB', async () => {
		const baseline = await captureBaseline();
		expect(baseline.contract.form?.find((sample) => sample.role === 'color')).toMatchObject({
			uvSet: 0,
			basis: 'metric',
			repeat: [1.25, 0.625],
			rotation: 0.4,
			offset: [0.25, 0.5]
		});
		expect(baseline.contract.model?.find((sample) => sample.role === 'color')).toMatchObject({
			uvSet: 0,
			basis: 'identity',
			repeat: [1, 1],
			rotation: 0,
			offset: [0, 0]
		});
		expect(baseline.contract.uv1Mirrored?.find((sample) => sample.role === 'color')).toMatchObject({
			uvSet: 1,
			repeat: [2, 3],
			rotation: 1.2,
			offset: [0.1, 0.9]
		});
	});

	it('keeps the ORM channels, disabled normal and −Y convention explicit', async () => {
		const baseline = await captureBaseline();
		expect(baseline.contract.orm.roughness).toMatchObject({ component: 'g', invert: false });
		expect(baseline.contract.orm.metalness).toMatchObject({ component: 'b', invert: false });
		expect(baseline.contract.orm.occlusion).toMatchObject({ component: 'r', invert: false });
		expect(baseline.contract.disabledNormal.normal).toBeNull();
					expect(baseline.contract.disabledNormal.provenance).toEqual({ source: 'disabled' });
		expect(baseline.contract.minusYNormal).toEqual({ convention: '-Y', normalScale: 1.4 });
	});

	it('records the pre-change pixel capture as a completed PR B prerequisite', async () => {
		const baseline = await captureBaseline();
		expect(baseline.pixelBaseline.status).toBe('captured');
		expect(baseline.pixelBaseline.requirement).toContain('Before replacing the Scene resolver or sampling path');
	});

	it('matches the committed baseline', async () => {
		const current = await captureBaseline();
		if (process.env.S8_BASELINE === 'write') {
			writeFileSync(BASELINE_PATH, `${JSON.stringify(current, null, 2)}\n`);
		}
		const committed = JSON.parse(readFileSync(BASELINE_PATH, 'utf8'));
		expect(current).toEqual(committed);
	});

	it('is deterministic across two captures', async () => {
		expect(await captureBaseline()).toEqual(await captureBaseline());
	});
});
